INSERT INTO `templates` (`id`, `title`, `value`, `template_type_id`, `system`, `created_at`, `updated_at`) VALUES
(1, 'Cilantro Report Sheet / Bulletin de Cilantro I (EN & FR)', '<p style=\"text-align: center;\"><span style=\"font-size: 12pt; color: #169179;\"><span style=\"color: #000000;\">{school.logo}</span></span></p>\n<p style=\"text-align: center;\"><span style=\"color: rgb(0, 0, 0);\"><strong><em><span style=\"font-size: 18pt;\">{school.name} ({school.code})</span></em></strong></span></p>\n<p style=\"text-align: center;\">( {school.address} )</p>\n<p style=\"text-align: center;\">&nbsp;</p>\n<table style=\"border-collapse: collapse; width: 100%; height: 135.219px; border: 3px none rgb(0, 0, 0); margin-left: auto; margin-right: auto;\" border=\"1\"><colgroup><col style=\"width: 8.33335%;\"><col style=\"width: 8.33335%;\"><col style=\"width: 16.6667%;\"><col style=\"width: 33.3333%;\"><col style=\"width: 8.33335%;\"><col style=\"width: 8.33335%;\"><col style=\"width: 8.33335%;\"><col style=\"width: 8.33335%;\"></colgroup>\n<tbody>\n<tr style=\"height: 135.219px;\">\n<td style=\"border-style: none; height: 135.219px; border-color: rgb(0, 0, 0); border-width: 3px;\">&nbsp;</td>\n<td style=\"border-style: none; height: 135.219px; border-color: rgb(0, 0, 0); border-width: 3px;\">&nbsp;</td>\n<td style=\"text-align: center; vertical-align: middle; background-color: rgb(206, 212, 217); height: 135.219px; border-color: rgb(0, 0, 0); border-width: 3px;\" colspan=\"4\">\n<p><span style=\"color: rgb(0, 0, 0); font-size: 24pt;\"><strong>ACADEMIC REPORT SHEET / BULLETIN DE NOTES</strong></span></p>\n<p><span style=\"color: rgb(0, 0, 0); font-size: 24pt;\"><strong><span style=\"font-size: 18pt; color: rgb(0, 0, 0);\">{school.term}</span></strong></span></p>\n<p><span style=\"color: rgb(0, 0, 0); font-size: 24pt;\"><strong><span style=\"font-size: 18pt; color: rgb(0, 0, 0);\"><span style=\"font-size: 18pt; color: rgb(35, 111, 161);\"><span style=\"font-size: 12pt; color: rgb(186, 55, 42);\">{school.academic-year}</span></span></span></strong></span></p>\n</td>\n<td style=\"border-style: none; height: 135.219px; border-color: rgb(0, 0, 0); border-width: 3px;\">&nbsp;</td>\n<td style=\"border-style: none; height: 135.219px; border-color: rgb(0, 0, 0); border-width: 3px;\">&nbsp;</td>\n</tr>\n</tbody>\n</table>\n<p style=\"text-align: center;\">&nbsp;</p>\n<hr>\n<p>&nbsp;</p>\n<table style=\"border-collapse: collapse; width: 100%; height: 210.875px; border-width: 1px; border-style: none;\" border=\"1\"><colgroup><col style=\"width: 50%;\"><col style=\"width: 50%;\"></colgroup>\n<tbody>\n<tr style=\"height: 53.2188px;\">\n<td style=\"height: 53.2188px; border-style: none;\"><span style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\"><strong>STUDENT NAME / NOM D\'&Eacute;TUDIANT:</strong></span> {student.full-name}</span></td>\n<td style=\"height: 53.2188px; border-style: none;\">\n<p><span style=\"font-size: 12pt;\"><span style=\"color: #169179;\"><strong><span style=\"color: rgb(0, 0, 0);\">STUDENT DATE OF BIRTH / DATE DE NAISSANCE DE L\'&Eacute;TUDIANT:</span>&nbsp;</strong><span style=\"color: #000000;\">{student.date-of-birth}</span></span></span></p>\n</td>\n</tr>\n<tr style=\"height: 53.2188px;\">\n<td style=\"height: 53.2188px; border-style: none;\">\n<p><span style=\"font-size: 12pt;\"><strong><strong style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\">STUDENT MATRICULE / MATRICULE D\'&Eacute;TUDIANT:</span> </strong></strong>{student.matricule}</span></p>\n</td>\n<td style=\"height: 53.2188px; border-style: none;\"><span style=\"font-size: 12pt;\"><strong><span style=\"color: rgb(0, 0, 0);\">STUDENT GUARDIAN/PARENT / TUTEUR/PARENT DE L\'&Eacute;TUDIANT:</span> </strong>{student.guardian}</span></td>\n</tr>\n<tr style=\"height: 51.2188px;\">\n<td style=\"height: 51.2188px; border-style: none;\"><span style=\"font-size: 12pt;\"><strong><span style=\"color: rgb(35, 111, 161);\"><span style=\"color: rgb(0, 0, 0);\">STUDENT CLASS / CLASSE D\'&Eacute;TUDIANT:</span>&nbsp;</span></strong><span style=\"color: rgb(35, 111, 161);\"><span style=\"color: rgb(0, 0, 0);\">{student.class}</span></span></span></td>\n<td style=\"height: 51.2188px; border-style: none;\"><span style=\"font-size: 12pt;\"><strong><strong style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\">REPEATER / REDOUBLANT:</span> </strong></strong>{student.is-repeater}</span></td>\n</tr>\n<tr style=\"height: 53.2188px;\">\n<td style=\"height: 53.2188px; border-style: none;\"><span style=\"font-size: 12pt;\"><strong><strong style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\">ENROLLMENT / EFFECTIF:</span> </strong></strong>{student.enrollment}</span></td>\n<td style=\"height: 53.2188px; border-style: none;\"><strong style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\">CLASS MASTER / PROF PRINC.:</span> </strong><span style=\"font-size: 12pt;\">{class.student-class-master}</span></td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<hr>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p><span style=\"font-size: 12pt;\">{result.student-result}</span></p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p><span style=\"font-size: 12pt;\">&nbsp;</span></p>\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"1\"><colgroup><col style=\"width: 33.3333%;\"><col style=\"width: 33.3333%;\"><col style=\"width: 33.3333%;\"></colgroup>\n<tbody>\n<tr>\n<td><strong>&nbsp;STUDENT PROFILE / PROFIL DE L\'&Eacute;TUDIANT</strong></td>\n<td><strong>&nbsp; CLASS PROFILE / PROFIL DE CLASSE</strong></td>\n<td><strong>&nbsp; DISCIPLINE</strong></td>\n</tr>\n<tr>\n<td rowspan=\"3\">\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong>&nbsp;&nbsp;</strong></span></span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong><span style=\"color: rgb(0, 0, 0);\">&nbsp; Term Av</span></strong><span style=\"color: rgb(0, 0, 0);\"><strong>erage / </strong></span></span></span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\"><strong>&nbsp; Moyenne Trimestriel</strong>:</span>&nbsp; &nbsp; &nbsp;{result.student-result-average}</span></p>\n<p>&nbsp;</p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong>&nbsp; <span style=\"color: rgb(0, 0, 0);\">Term Rank / </span></strong></span></span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\"><strong>&nbsp; Rang Trimestriel</strong>:</span>&nbsp; &nbsp; &nbsp;{result.student-result-position}&nbsp; /&nbsp; {class.student-class-size}</span></p>\n<p>&nbsp;</p>\n</td>\n<td rowspan=\"3\">\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong>&nbsp; </strong></span></span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong><span style=\"color: rgb(0, 0, 0);\">&nbsp; Class Term Av</span></strong><span style=\"color: rgb(0, 0, 0);\"><strong>erage / </strong></span></span></span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\"><strong>&nbsp; Moyenne Classe</strong>:</span>&nbsp; &nbsp; &nbsp;{result.class-result-average}</span></p>\n<p>&nbsp;</p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong>&nbsp; <span style=\"color: rgb(0, 0, 0);\">Highest Student Av</span></strong><span style=\"color: rgb(0, 0, 0);\"><strong>erage / </strong></span></span></span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\"><strong>&nbsp; Moyenne &eacute;tudiante la plus &eacute;lev&eacute;e</strong>:</span>&nbsp; &nbsp; &nbsp;{result.class-result-hs-average}</span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong>&nbsp;</strong></span></span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong>&nbsp; <span style=\"color: rgb(0, 0, 0);\">Lowest Student Av</span></strong><span style=\"color: rgb(0, 0, 0);\"><strong>erage / </strong></span></span></span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\"><strong>&nbsp; Moyenne &eacute;tudiante la plus basse</strong>:</span>&nbsp; &nbsp; &nbsp;{result.class-result-ls-average}</span></p>\n<p>&nbsp;</p>\n</td>\n<td rowspan=\"3\">\n<p>&nbsp;</p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong><span style=\"color: rgb(0, 0, 0);\">&nbsp; <span style=\"color: rgb(35, 111, 161);\"><span style=\"color: rgb(0, 0, 0);\">Total Hours Of </span></span>Absences /</span></strong></span></span></p>\n<p><span style=\"font-size: 12pt; color: rgb(0, 0, 0);\">&nbsp; <span style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\"><strong>Nombre total d\'heures d\'absences</strong></span></span>:&nbsp; &nbsp;&nbsp;</span><span style=\"font-size: 12pt;\"> {student.absences}</span></p>\n<p>&nbsp;</p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong><span style=\"color: rgb(0, 0, 0);\">&nbsp; Total Hours Of Punishment / </span></strong></span></span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\"><strong>&nbsp; Nombre total d\'heures de punition</strong>:&nbsp; &nbsp;&nbsp;</span> {discipline.student-discipline-record-hours-of-punishment}</span></p>\n<p>&nbsp;</p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong>&nbsp;<span style=\"color: rgb(0, 0, 0);\"> Total Number Of Warnings / </span></strong></span></span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(0, 0, 0);\"><strong>&nbsp; Nombre total d\'avertissements</strong>:&nbsp; &nbsp;&nbsp;</span> {discipline.student-discipline-record-number-of-warnings}</span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong>&nbsp;</strong></span></span></p>\n<p><span style=\"font-size: 12pt;\"><span style=\"color: rgb(35, 111, 161);\"><strong>&nbsp; <span style=\"color: rgb(0, 0, 0);\">Total Number Of Days Of Suspension / </span></strong></span></span></p>\